head.script:
// 담당 범위 : partialCheckNextClick 가이드 전 항목
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성, Body Column 에만 설정)
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > partialCheckNextClick]<br/>Header Column 의 CheckBox 가 부분 체크 상태일때 Header Column 의 CheckBox 를 클릭 시 Body Column 의 선택 처리 방식을 설정합니다.",
    "validation" : [
        "Header Column 과 Body Column 의 inputType 속성이 모두 'checkbox' 인 경우에 동작합니다.",
        "'' 설정 시, Body Column 의 checkAlways 속성값에 따라 동작이 달라집니다.",
        "미설정 시, Body Column 의 checkAlways 속성값에 따라 동작이 달라집니다.",
        "'' 설정 시, checkAlways='true' 이면 Header Column 의 CheckBox 클릭 시 전체 선택됩니다.",
        "'' 설정 시, checkAlways='false' 이면 Header Column 의 CheckBox 클릭 시 전체 해제됩니다.",
        "check 설정 시, Header Column 의 CheckBox 클릭 시 전체 선택됩니다.",
        "uncheck 설정 시, Header Column 의 CheckBox 클릭 시 전체 해제됩니다.",
        "Header Column 과 같은 위치에 있는 Body Column 에 설정합니다.",
        "Body Column 의 일부 Row 만 체크되면 Header Column 의 CheckBox 가 부분 체크(indeterminate) 상태로 표시됩니다.",
    ]
}



scwin.gVar = {
    // Header 체크박스 클릭 직전 상태 (mousedown 시점 기록)
    "beforeHeader" : ""
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_partialCheckNextClick.setValue("");
    con_checkAlways.setValue("2");
    con_headerInputType.setValue("checkbox");
    con_bodyInputType.setValue("checkbox");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - partialCheckNextClick / checkAlways 는 Header chk Column(column3) 과 같은 위치(두번째)에 있는 Body chk Column 에만 설정 (validation 8)
//  - 초기 데이터는 일부 Row 만 체크(1, 3행)되어 생성 직후 Header 가 부분 체크 상태 (validation 9)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다, gdl_boolean 은 getText() 로 '' / 'true' / 'false' 판단)
    let cPartial = con_partialCheckNextClick.getValue();
    let cCheckAlways = con_checkAlways.getText();
    let cHeaderInputType = con_headerInputType.getValue();
    let cBodyInputType = con_bodyInputType.getValue();

    let attrPartial = '';
    if (cPartial === "__empty") {
        attrPartial = ' partialCheckNextClick=""';
    } else if (cPartial !== '') {
        attrPartial = ' partialCheckNextClick="' + cPartial + '"';
    }
    let attrCheckAlways = (cCheckAlways === '') ? '' : ' checkAlways="' + cCheckAlways + '"';

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 옵션 속성은 Header chk 와 같은 위치의 Body chk Column 에 설정, 초기 데이터는 1, 3행만 체크\n[절차] 부분 체크 상태에서 chk Header 체크박스 클릭 (전체 선택/해제 후에는 Body 체크박스 하나를 클릭해 다시 부분 체크로 만든 뒤 반복)\n[확인] 결과창의 클릭 전 Header 상태와 클릭 후 행별 chk 값"', '', 'label1');

    // dataList 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="product" name="product" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "product" : "노트북", "chk" : "0" },
        { "product" : "모니터", "chk" : "1" },
        { "product" : "키보드", "chk" : "0" },
        { "product" : "마우스", "chk" : "1" },
        { "product" : "프린터", "chk" : "0" }
    ], false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let eList = $c.gcm.createEList(["onviewchange"]);
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + eList + ' dataList="data:dlt_bind" id="" style="width:320px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="column1" value="상품명"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="' + cHeaderInputType + '" id="column2" value="chk"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="product" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="' + cBodyInputType + '" id="chk" value=""' + attrCheckAlways + attrPartial + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // Header 체크박스 클릭 감지 (Header 를 다시 그려도 유지되도록 grid render 에서 capture 단계로 위임 처리)
    target1.render.addEventListener("mousedown", scwin.onHeaderCheckMouseDown, true);
    target1.render.addEventListener("click", scwin.onHeaderCheckClick, true);

    // 생성 직후 Header 상태 출력 (validation 9 : 일부 Row 체크 시 부분 체크 표시)
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("생성 직후 -> " + scwin.getCheckInfo());
    }, 100);
}



// Header 의 chk 체크박스 요소 반환 (Header inputType 이 checkbox 가 아니면 null)
scwin.getHeaderCheckbox = function () {
    return document.querySelector("#" + target1.id + "_column2 input[type='checkbox']");
}



// Header 체크 상태 문자열
scwin.getHeaderState = function () {
    let hChk = scwin.getHeaderCheckbox();
    return hChk ? "checked=" + hChk.checked + ", indeterminate=" + hChk.indeterminate : "체크박스 없음";
}



// 행별 chk 값과 Header 체크 상태 문자열
scwin.getCheckInfo = function () {
    let arr = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        arr.push(i + "행=" + dlt_bind.getCellData(i, "chk"));
    }
    return "chk 값 : " + arr.join(", ") + " / Header : " + scwin.getHeaderState();
}



// Header 체크박스 클릭 직전 상태 기록
scwin.onHeaderCheckMouseDown = function (e) {
    let hChk = scwin.getHeaderCheckbox();
    if (!hChk || e.target !== hChk) {
        return;
    }
    scwin.gVar.beforeHeader = scwin.getHeaderState();
}



// validation 1 ~ 8 : 부분 체크 상태에서 Header 체크박스 클릭 후 행별 값
scwin.onHeaderCheckClick = function (e) {
    let hChk = scwin.getHeaderCheckbox();
    if (!hChk || e.target !== hChk) {
        return;
    }
    let before = scwin.gVar.beforeHeader;
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("Header 클릭 (클릭 전 Header : " + before + ") -> " + scwin.getCheckInfo());
    }, 50);
}



// validation 9 : Body 체크박스로 값 변경 후 Header 체크 상태
scwin.target1_onviewchange = function (info) {
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue(info.rowIndex + "행 변경 (" + info.oldValue + " -> " + info.newValue + ") -> " + scwin.getCheckInfo());
    }, 50);
}
